    'si': 'ඔබට සාර්ථකව උඩුගත කළ ගොනු සමඟ ඉදිරියට යා හැක.',
    'simple': 'You can continue with the files that were uploaded successfully.',
    'sk': 'Môžete pokračovať s úspešne nahranými súbormi.',
    'sl': 'Lahko nadaljujete z uspešno prenesenimi datotekami.',
    'sm': 'E mafai ona fa\'aauau ma fa\'amaumauga na fa\'aumaina ma le manuia.',
    'sn': 'Unogona kuenderera nemafaira akatumirwa zvakanaka.',
    'so': 'Waxaad sii wadi kartaa faylalka si guul leh loo soo geliyay.',
    'sq': 'Mund të vazhdoni me skedarët e ngarkuar me sukses.',
    'sr': 'Можете наставити са успешно отпремљеним датотекама.',
    'srn': 'Yu kan go doro nanga den file di ben seni kon bun.',
    'ss': 'Ungachubeka ngemafayela lafakwe ngemphume-lehle.',
    'st': 'O ka tswela pele ka difaele tse jarisitsweng ka katleho.',
    'stq': 'Du koast mäd do mäd Ärfoulch hoocheeloate Doatäie fääregunge.',
    'su': 'Anjeun tiasa neruskeun jeung file anu parantos dimuatkeun.',
    'sv': 'Du kan fortsätta med de filer som laddats upp.',
    'sw': 'Unaweza kuendelea na faili ambazo zimepakiwa kwa mafanikio.',
    'szl': 'Możesz kōntynuować ze pomyślnie wysłanymi plikami.',
    'ta': 'வெற்றிகரமாக பதிவேற்றிய கோப்புகளுடன் நீங்கள் தொடரலாம்.',
    'te': 'మీరు విజయవంతంగా అప్‌లోడ్ చేసిన ఫైల్‌లతో కొనసాగించవచ్చు.',
    'tet': 'Ita bele kontinua ho dokumentu sira ne\'ebé hatama ho susesu.',
    'tg': 'Шумо метавонед бо файлҳои бомуваффақият боргузоришуда идома диҳед.',
    'th': 'คุณสามารถดำเนินการต่อไปกับไฟล์ที่อัปโหลดสำเร็จแล้ว',
    'ti': 'ብዓወት ምስ ዝተጸዓኑ ፋይላት ክትቅጽል ትኽእል ኢኻ።',
    'tk': 'Üstünlikli ýüklenen faýllar bilen dowam edip bilersiňiz.',
    'tl': 'Maaari kang magpatuloy sa mga file na matagumpay na na-upload.',
    'tn': 'O ka tswelela ka difaele tse di laoletsweng ka katlego.',
    'to': 'Te ke lava ʻo hoko atu mo e ngaahi faile kuo ʻosi hakeaki lelei.',
    'tpi': 'Yu ken go het wantaim ol fail we yu salim pinis gutpela.',
    'tr': 'Başarıyla yüklenen dosyalarla devam edebilirsiniz.',
    'ts': 'U nga ya emahlweni hi tifayela leti nga rhumeriweke hi ndlela leyi humeleleke.',
    'tt': 'Сез уңышлы йөкләнгән файллар белән дәвам итә аласыз.',
    'tum': 'Mungagwira ntchito na mafayilo ayo mwakwaniska kupwilisha.',
    'tw': 'Wobɛtumi akɔ so wo nkrataa a wode akɔto soro akyi.',
    'ty': 'E ti\'a ia oe e fa\'aohie i te mau tāpa\'o papa i ha\'apūro\'i ma te maita\'i.',
    'tyv': 'Силер чедимчелиг киирген файлдарга уламчылап болур силер.',
    'udm': 'Тӥляд быгатӥськоды азьланьтыны кабул карем файлъёсын.',
    'ug': 'سىز مۇۋەپپەقىيەتلىك يۈكلەنگەن ھۆججەتلەر بىلەن داۋاملاشتۇرالايسىز.',
    'uk': 'Ви можете продовжити з успішно завантаженими файлами.',
    'ur': 'آپ کامیابی سے اپلوڈ کی گئی فائلوں کے ساتھ جاری رکھ سکتے ہیں۔',
    'uz': 'Siz muvaffaqiyatli yuklangan fayllar bilan davom etishingiz mumkin.',
    've': 'Ni nga isa u bvela phanda nga faela dzo no ṱanganedzwa zwavhuḓi.',
    'vec': 'Ti pol continuar coi file caricà con suceso.',
    'vep': 'Voižet jatkta satusekahas üläpandud failoidenke.',
    'vi': 'Bạn có thể tiếp tục với các tệp đã tải lên thành công.',
    'vls': 'Je kunt deurgoan me de bestandn die succesvol opgeload zyn.',
    'vo': 'Kanol fuön ko pads perakedaföl benosädiko.',
    'wa': 'Vos ploz continouwer avou les fitchîs retchedjîs avou succès.',
    'war': 'Puydi ka magpadayon ha mga file nga ma-ura nga gin-upload.',
    'wo': 'Mën ngay kontinéé ak dencukaayu yi jub.',
    'wuu': '侬可以继续处理上传成功个文件。',
    'xal': 'Чи амр хадһлҗ болһсн боомгудар цааранднь кевтҗ чаднач.',
    'xh': 'Ungaqhubeka ngeefayile ezilayishwe ngempumelelo.',
    'xmf': 'შეგილებუნა განაგრძო წარმატებით გეთხილაფირი ფაილეფით.',
    'yi': 'איר קענט ווייטער מיט די דערפֿאלגרייך ארויפֿגעלאדענע טעקעס.',
    'yo': 'O le tẹsiwaju pẹlu awọn faili ti o ti gbe soke ni ifijišẹ.',
    'yue': '你可以繼續處理成功上載嘅檔案。',
    'za': 'Mwngz lix bae dauq cawj youq gya fwngz song caux rai neix.',
    'zea': 'Je kan deu\'gaè mie de bestan die succesvol opheload bin.',
    'zh': '你可以继续处理成功上传的文件。',
    'zh-classical': '閣下能以成功上載之檔案繼續。',
    'zh-min-nan': '你可以繼續處理已經上傳成功的檔案。',
    'zh-yue': '你可以繼續處理成功上載嘅檔案。',
    'zu': 'Ungaqhubeka ngamafayela alayishwe ngempumelelo.',
    'sat': 'ᱟᱢ ᱫᱚ ᱥᱟᱱᱟᱢ ᱠᱮᱣᱛᱮᱱᱟᱜ ᱯᱷᱟᱭᱞ ᱥᱟᱞᱟᱜ ᱛᱮ ᱞᱮᱛᱟᱲ ᱫᱟᱲᱮᱭᱟᱜᱼᱟᱢ ᱾',
    'kok': 'तुमी यशस्वीपणान अपलोड केल्ल्या फायलींसंगटाक चालू दवरूं येता।',
    'tcy': 'ಈರ್ ಸಾಫಲ್ಯದಿಂಚ ಅಪ್ಲೋಡ್ ಮಲ್ತಿನ ಫೈಲ್ಲೊಲೆನ್ ಮುಂದುವರೆಸಯೆರಾ.',
    'bho': 'आप सफलतापूर्वक अपलोड कइल गइल फाइल सभ के साथ जारी रख सकत बानी।',
    'hne': 'आप मन सफलतापूर्वक अपलोड करे फाइल मन के साथ आगू बढ़ सकथव।',
    'doi': 'तुस सफलतापूर्वक अपलोड कीती गेदियां फाइलां कन्नै जारी रक्खी सकदे ओ।',
    'mwr': 'आप सफलतापूर्वक अपलोड करी गई फाइलां साथे जारी राख सकौ छौ।',
    'mag': 'अहां सफलतापूर्वक अपलोड कैल गेल फाइल सभक संग जारी राखि सकै छी।',
    'mni': 'নহাক্না মায়ৈ পাংথোকনা অপলোদ তৌখ্রবা ফাইলশিংগা লোয়ননা মখা চত্না ঙম্মী।',
    'brx': 'नों मोजां मोना आपलोद खालामबाय थानाय फाइलफोरजों सोलायनो हागौ।',
